export const LANGS = [
  { code: 'uz', label: "O'zbek" },
  { code: 'ru', label: '\u0420\u0443\u0441\u0441\u043a\u0438\u0439' },
  { code: 'en', label: 'English' },
];

export function getLang() {
  return localStorage.getItem('lang') || 'uz';
}
export function setLang(code) {
  localStorage.setItem('lang', code);
}

export function t(key, vars) {
  const lang = getLang();
  let str = (DICT[lang] && DICT[lang][key]) ?? DICT.uz[key] ?? key;
  if (vars) {
    for (const k in vars) str = str.replace(`{${k}}`, vars[k]);
  }
  return str;
}

// Shartnoma matni tarjimalari (asosiy huquqiy matn) — har til uchun.
export function contractText() {
  const lang = getLang();
  const T = {
    uz: `
<p><b>TO'GARAK RAHBARI BILAN TUZILADIGAN SHARTNOMA (namuna)</b></p>
<p>Ushbu shartnoma "TUGARAK+" tizimi ma'muriyati (keyingi o'rinlarda — "Ma'muriyat") va to'garak rahbari sifatida ro'yxatdan o'tayotgan shaxs (keyingi o'rinlarda — "Rahbar") o'rtasida tuziladi.</p>
<p>1. Rahbar tizimga kiritilgan o'quvchilar ro'yxati va baholash ma'lumotlarining to'g'riligiga shaxsan javobgardir.</p>
<p>2. Rahbar o'quvchilarning shaxsiy ma'lumotlarini (jumladan, qo'lda yozilgan ro'yxatlar rasmini) faqat ta'lim maqsadlarida ishlatishga majburdir.</p>
<p>3. Ma'muriyat Rahbar tomonidan yuborilgan ro'yxatdan o'tish arizasini ko'rib chiqib, tasdiqlash yoki rad etish huquqiga ega.</p>
<p>4. Tasdiqlangandan so'ng Rahbar tizimning barcha imkoniyatlaridan foydalanish huquqiga ega bo'ladi.</p>
<p>5. Rahbar tekshiruvchi tashkilotlar tomonidan so'ralganda, o'z guruhi bo'yicha rasmiy hisobotni taqdim etishga majburdir.</p>
<p>6. <b>To'lovlar bo'yicha shartlar:</b> tizimdan foydalanish Ma'muriyat belgilagan tartibda pullik xizmat hisoblanishi mumkin. To'lov summasi, muddati va usuli Ma'muriyat tomonidan Rahbarga alohida xabar qilinadi. To'lov amalga oshirilmagan taqdirda Ma'muriyat hisobni vaqtincha to'xtatib qo'yish huquqiga ega.</p>
<p>7. Ushbu shartnoma elektron shaklda, "Roziman" tugmasini bosish orqali imzolangan hisoblanadi.</p>
<p>8. <b>Aloqa va murojaat:</b> savol, taklif yoki shikoyatlar bo'yicha:</p>
<p style="margin-left:6px;">\u{1F4E7} idrizmedia@gmail.com<br>\u{1F4F7} @normurodov_izzatillo<br>\u2708\uFE0F @ziyomap</p>`,
    ru: `
<p><b>\u0414\u041e\u0413\u041e\u0412\u041e\u0420 \u0421 \u0420\u0423\u041a\u041e\u0412\u041e\u0414\u0418\u0422\u0415\u041b\u0415\u041c \u041a\u0420\u0423\u0416\u041a\u0410 (\u043e\u0431\u0440\u0430\u0437\u0435\u0446)</b></p>
<p>\u041d\u0430\u0441\u0442\u043e\u044f\u0449\u0438\u0439 \u0434\u043e\u0433\u043e\u0432\u043e\u0440 \u0437\u0430\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f \u043c\u0435\u0436\u0434\u0443 \u0430\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u0435\u0439 \u0441\u0438\u0441\u0442\u0435\u043c\u044b "TUGARAK+" (\u0434\u0430\u043b\u0435\u0435 \u2014 "\u0410\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f") \u0438 \u043b\u0438\u0446\u043e\u043c, \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u0443\u044e\u0449\u0438\u043c\u0441\u044f \u0432 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435 \u0440\u0443\u043a\u043e\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044f \u043a\u0440\u0443\u0436\u043a\u0430 (\u0434\u0430\u043b\u0435\u0435 \u2014 "\u0420\u0443\u043a\u043e\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c").</p>
<p>1. \u0420\u0443\u043a\u043e\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u043d\u0435\u0441\u0451\u0442 \u043b\u0438\u0447\u043d\u0443\u044e \u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u0437\u0430 \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c \u0441\u043f\u0438\u0441\u043a\u0430 \u0443\u0447\u0435\u043d\u0438\u043a\u043e\u0432 \u0438 \u0434\u0430\u043d\u043d\u044b\u0445 \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u043d\u0438\u044f.</p>
<p>2. \u0420\u0443\u043a\u043e\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u043e\u0431\u044f\u0437\u0443\u0435\u0442\u0441\u044f \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c \u043b\u0438\u0447\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u0443\u0447\u0435\u043d\u0438\u043a\u043e\u0432 \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u0446\u0435\u043b\u044f\u0445.</p>
<p>3. \u0410\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f \u0432\u043f\u0440\u0430\u0432\u0435 \u0440\u0430\u0441\u0441\u043c\u043e\u0442\u0440\u0435\u0442\u044c \u0437\u0430\u044f\u0432\u043a\u0443 \u0438 \u043e\u0434\u043e\u0431\u0440\u0438\u0442\u044c \u0438\u043b\u0438 \u043e\u0442\u043a\u043b\u043e\u043d\u0438\u0442\u044c \u0435\u0451.</p>
<p>4. \u041f\u043e\u0441\u043b\u0435 \u043e\u0434\u043e\u0431\u0440\u0435\u043d\u0438\u044f \u0420\u0443\u043a\u043e\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u043f\u043e\u043b\u0443\u0447\u0430\u0435\u0442 \u0434\u043e\u0441\u0442\u0443\u043f \u043a\u043e \u0432\u0441\u0435\u043c \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u044f\u043c \u0441\u0438\u0441\u0442\u0435\u043c\u044b.</p>
<p>5. \u041f\u043e \u0437\u0430\u043f\u0440\u043e\u0441\u0443 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u044e\u0449\u0438\u0445 \u043e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0446\u0438\u0439 \u0420\u0443\u043a\u043e\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u043e\u0431\u044f\u0437\u0430\u043d \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u043e\u0442\u0447\u0451\u0442 \u043f\u043e \u0441\u0432\u043e\u0435\u0439 \u0433\u0440\u0443\u043f\u043f\u0435.</p>
<p>6. <b>\u0423\u0441\u043b\u043e\u0432\u0438\u044f \u043e\u043f\u043b\u0430\u0442\u044b:</b> \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435 \u0441\u0438\u0441\u0442\u0435\u043c\u044b \u043c\u043e\u0436\u0435\u0442 \u044f\u0432\u043b\u044f\u0442\u044c\u0441\u044f \u043f\u043b\u0430\u0442\u043d\u043e\u0439 \u0443\u0441\u043b\u0443\u0433\u043e\u0439 \u043f\u043e \u0443\u0441\u043c\u043e\u0442\u0440\u0435\u043d\u0438\u044e \u0410\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u0438. \u0421\u0443\u043c\u043c\u0430, \u0441\u0440\u043e\u043a\u0438 \u0438 \u0441\u043f\u043e\u0441\u043e\u0431 \u043e\u043f\u043b\u0430\u0442\u044b \u0441\u043e\u043e\u0431\u0449\u0430\u044e\u0442\u0441\u044f \u0420\u0443\u043a\u043e\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044e \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e. \u041f\u0440\u0438 \u043d\u0435\u0441\u0432\u043e\u0435\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u0439 \u043e\u043f\u043b\u0430\u0442\u0435 \u0410\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f \u0432\u043f\u0440\u0430\u0432\u0435 \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e \u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u0434\u043e\u0441\u0442\u0443\u043f.</p>
<p>7. \u041d\u0430\u0441\u0442\u043e\u044f\u0449\u0438\u0439 \u0434\u043e\u0433\u043e\u0432\u043e\u0440 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043d\u043d\u044b\u043c \u0432 \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043d\u043d\u043e\u043c \u0432\u0438\u0434\u0435 \u043f\u0440\u0438 \u043d\u0430\u0436\u0430\u0442\u0438\u0438 \u043a\u043d\u043e\u043f\u043a\u0438 "\u0421\u043e\u0433\u043b\u0430\u0441\u0435\u043d".</p>
<p>8. <b>\u041a\u043e\u043d\u0442\u0430\u043a\u0442\u044b:</b></p>
<p style="margin-left:6px;">\u{1F4E7} idrizmedia@gmail.com<br>\u{1F4F7} @normurodov_izzatillo<br>\u2708\uFE0F @ziyomap</p>`,
    en: `
<p><b>AGREEMENT WITH THE CLUB LEADER (template)</b></p>
<p>This agreement is made between the "TUGARAK+" system administration (hereinafter — the "Administration") and the person registering as a club leader (hereinafter — the "Leader").</p>
<p>1. The Leader is personally responsible for the accuracy of the student roster and grading data entered into the system.</p>
<p>2. The Leader agrees to use students' personal data (including photos of handwritten rosters) only for educational purposes.</p>
<p>3. The Administration has the right to review, approve, or reject the Leader's registration application.</p>
<p>4. Once approved, the Leader gains access to all system features (creating groups, adding students, grading, generating reports).</p>
<p>5. Upon request from inspecting organizations, the Leader must provide an official report on their group.</p>
<p>6. <b>Payment terms:</b> use of the system may be a paid service as determined by the Administration. The amount, timing, and method of payment will be communicated to the Leader separately. If payment is not made or is delayed, the Administration may temporarily suspend the account.</p>
<p>7. This agreement is considered electronically signed by clicking the "I agree" button.</p>
<p>8. <b>Contact:</b> for questions, suggestions, or complaints:</p>
<p style="margin-left:6px;">\u{1F4E7} idrizmedia@gmail.com<br>\u{1F4F7} @normurodov_izzatillo<br>\u2708\uFE0F @ziyomap</p>`,
  };
  return T[lang] || T.uz;
}
